PLANILHA_SALDOS_ID = "1NFHtHLaBdzukM0JltkzEExro8zZj1ktD"
PLANILHA_SALDOS_URL = (
    f"https://docs.google.com/spreadsheets/d/{PLANILHA_SALDOS_ID}/export?format=xlsx"
)

MESES_PLANILHA = {
    1: "JANEIRO", 2: "FEVEREIRO", 3: "MARÇO", 4: "ABRIL",
    5: "MAIO", 6: "JUNHO", 7: "JULHO", 8: "AGOSTO",
    9: "SETEMBRO", 10: "OUTUBRO", 11: "NOVEMBRO", 12: "DEZEMBRO",
}

MESES_TEXTO = {
    "JANEIRO": 1, "FEVEREIRO": 2, "MARCO": 3, "ABRIL": 4,
    "MAIO": 5, "JUNHO": 6, "JULHO": 7, "AGOSTO": 8,
    "SETEMBRO": 9, "OUTUBRO": 10, "NOVEMBRO": 11, "DEZEMBRO": 12,
}


def _data_saldo(valor: object, ano: int, mes_padrao: int) -> pd.Timestamp:
    """Converte datas reais do Excel e textos como '30 DE JULHO'."""
    if isinstance(valor, (pd.Timestamp, date)):
        return pd.Timestamp(valor).normalize()

    convertido = pd.to_datetime(valor, errors="coerce", dayfirst=True)
    if not pd.isna(convertido):
        return pd.Timestamp(convertido).normalize()

    texto = norm_text(valor)
    match = re.search(r"(\d{1,2})\s+DE\s+([A-Z]+)", texto)
    if not match:
        return pd.NaT

    dia = int(match.group(1))
    mes = MESES_TEXTO.get(match.group(2), mes_padrao)
    try:
        return pd.Timestamp(year=ano, month=mes, day=dia)
    except ValueError:
        return pd.NaT


@st.cache_data(ttl=60, show_spinner=False)
def baixar_aba_saldos(nome_aba: str) -> pd.DataFrame:
    """Lê ao vivo o intervalo A4:L31 de uma aba do Google Sheets."""
    url = f"https://docs.google.com/spreadsheets/d/{PLANILHA_SALDOS_ID}/gviz/tq"
    resposta = requests.get(
        url,
        params={
            "tqx": "out:csv",
            "sheet": nome_aba,
            "range": "A4:L31",
            "_": str(pd.Timestamp.now().value),  # evita resposta antiga de proxy/CDN
        },
        headers={"User-Agent": "Mozilla/5.0"},
        timeout=45,
        allow_redirects=True,
    )
    resposta.raise_for_status()

    conteudo = resposta.content
    tipo = resposta.headers.get("Content-Type", "").lower()
    inicio = conteudo[:250].decode("utf-8", errors="ignore").lower()
    if not conteudo:
        raise ValueError(f"A aba {nome_aba} retornou conteúdo vazio.")
    if "text/html" in tipo or "<html" in inicio or "<!doctype" in inicio:
        raise PermissionError(
            "O Google retornou uma página HTML em vez dos dados da planilha. "
            "Confirme o compartilhamento por link e se o arquivo é uma Planilha Google."
        )

    try:
        quadro = pd.read_csv(io.BytesIO(conteudo), header=None, dtype=str)
    except Exception as exc:
        raise ValueError(f"Não foi possível interpretar a aba {nome_aba}: {exc}") from exc

    # O gviz pode omitir colunas vazias no fim. Garante A:L.
    quadro = quadro.reindex(columns=range(12))
    return quadro


def _numero_br_saldo(valor: object) -> float | None:
    """Converte números e valores monetários brasileiros vindos do Google Sheets."""
    if valor is None or (isinstance(valor, float) and pd.isna(valor)):
        return None
    if isinstance(valor, (int, float, np.number)):
        return float(valor)

    texto = str(valor).strip()
    if not texto:
        return None

    negativo = texto.startswith("(") and texto.endswith(")")
    texto = texto.replace("R$", "").replace(" ", "").replace("\u00a0", "")
    texto = texto.replace("(", "").replace(")", "")

    # Padrão brasileiro: 1.234.567,89
    if "," in texto:
        texto = texto.replace(".", "").replace(",", ".")
    else:
        # Sem vírgula: mantém ponto como decimal quando houver apenas um.
        if texto.count(".") > 1:
            texto = texto.replace(".", "")

    texto = re.sub(r"[^0-9.\-]", "", texto)
    if texto in {"", "-", ".", "-."}:
        return None
    try:
        numero = float(texto)
        return -numero if negativo else numero
    except ValueError:
        return None


def buscar_saldo_drive(data_referencia: date | None = None) -> dict:
    """
    Consulta ao vivo A4:L31 das abas mensais e retorna o saldo da data mais
    recente preenchida até hoje. A data está em A e o saldo na mesma linha em L.
    """
    referencia = data_referencia or date.today()
    registros: list[dict] = []
    erros: list[str] = []

    for mes_num, nome_aba in MESES_PLANILHA.items():
        try:
            quadro = baixar_aba_saldos(nome_aba)
        except Exception as exc:
            erros.append(f"{nome_aba}: {exc}")
            continue

        # A resposta já corresponde exatamente às linhas 4 a 31.
        for posicao, linha in quadro.iterrows():
            valor_data = linha.iloc[0] if len(linha) > 0 else None
            valor_saldo_original = linha.iloc[11] if len(linha) > 11 else None

            data_linha = _data_saldo(valor_data, referencia.year, mes_num)
            saldo_linha = _numero_br_saldo(valor_saldo_original)

            # "Preenchida" significa que ambas as células possuem valor válido.
            if pd.isna(data_linha) or saldo_linha is None:
                continue
            if pd.Timestamp(data_linha).date() > referencia:
                continue
            if pd.Timestamp(data_linha).year != referencia.year:
                continue

            registros.append(
                {
                    "Data": pd.Timestamp(data_linha).normalize(),
                    "Saldo": float(saldo_linha),
                    "Aba": nome_aba,
                    "Linha": int(posicao) + 4,
                }
            )

    if not registros:
        detalhe = " | ".join(erros[:4])
        raise ValueError(
            "Nenhum saldo válido foi encontrado ao vivo em A4:A31 e L4:L31. "
            + (f"Diagnóstico: {detalhe}" if detalhe else "")
        )

    base = pd.DataFrame(registros)
    # Maior data; em empate, prevalece a linha mais baixa da aba.
    base = base.sort_values(["Data", "Linha"], ascending=[True, True])
    ultimo = base.iloc[-1]

    return {
        "saldo": float(ultimo["Saldo"]),
        "data_saldo": pd.Timestamp(ultimo["Data"]).date(),
        "data_referencia": referencia,
        "origem": "Consulta ao vivo no Google Sheets · intervalo A4:L31",
        "aba": str(ultimo["Aba"]),
        "linha": int(ultimo["Linha"]),
    }


def norm_text(value: object) -> str:
    txt = "" if value is None else str(value)
    txt = unicodedata.normalize("NFKD", txt).encode("ascii", "ignore").decode("ascii")
    return re.sub(r"\s+", " ", txt.strip().upper())


def money_br(value: float) -> str:
    if pd.isna(value):
        return "R$ 0,00"
    sign = "-" if float(value) < 0 else ""
    txt = f"{abs(float(value)):,.2f}".replace(",", "X").replace(".", ",").replace("X", ".")
    return f"{sign}R$ {txt}"


def number_br(series: pd.Series) -> pd.Series:
    return pd.to_numeric(
        series.astype(str)
        .str.replace(r"[^0-9,.-]", "", regex=True)
        .str.replace(".", "", regex=False)
        .str.replace(",", ".", regex=False),
        errors="coerce",
    )


def read_raw_bytes(uploaded) -> bytes:
    uploaded.seek(0)
    return uploaded.read()


def decode_file(data: bytes) -> str:
    for enc in ("utf-8-sig", "cp1252", "latin1"):
        try:
            return data.decode(enc)
        except UnicodeDecodeError:
            continue
    return data.decode("latin1", errors="replace")


def find_header_line(lines: list[str], required_any: Iterable[str]) -> int:
    terms = [norm_text(x) for x in required_any]
    for idx, line in enumerate(lines):
        if ";" in line and any(term in norm_text(line) for term in terms):
            return idx
    raise ValueError("Não foi possível localizar o cabeçalho da tabela.")


def read_report_csv(data: bytes, expected: str) -> pd.DataFrame:
    signatures = {
        "cartoes": ["VLR.LIQ", "VLR LIQ", "DTA.VEN"],
        "receber": ["V.LIQUI", "CLIENTE", "VENCTO"],
        "pagar": ["VAL.LIQ", "FORNECEDOR", "DTA.VEN"],
    }
    lines = decode_file(data).splitlines()
    header_idx = find_header_line(lines, signatures[expected])
    df = pd.read_csv(
        io.StringIO("\n".join(lines[header_idx:])),
        sep=";", dtype=str, engine="python", on_bad_lines="skip",
    )
    df.columns = [norm_text(c) for c in df.columns]
    return df.dropna(how="all")


def first_existing(df: pd.DataFrame, candidates: list[str]) -> str:
    direct = {norm_text(c): c for c in df.columns}
    for candidate in candidates:
        if norm_text(candidate) in direct:
            return direct[norm_text(candidate)]
    for candidate in candidates:
        target = norm_text(candidate)
        for col in df.columns:
            if target in norm_text(col):
                return col
    raise ValueError(f"Coluna não encontrada: {', '.join(candidates)}")


def safe_column(raw: pd.DataFrame, candidates: list[str]) -> pd.Series:
    try:
        return raw[first_existing(raw, candidates)].fillna("").astype(str)
    except ValueError:
        return pd.Series("", index=raw.index, dtype="object")


def parse_source(data: bytes, source: str) -> pd.DataFrame:
    raw = read_report_csv(data, source)
    blank = pd.Series("", index=raw.index, dtype="object")
    document = origin_document = nsu = seller = account = history = blank.copy()

    if source == "cartoes":
        date_col = first_existing(raw, ["DTA.VEN", "DTA VEN", "VENCIMENTO"])
        value_col = first_existing(raw, ["VLR.LIQ", "VLR LIQ", "VALOR LIQUIDO"])
        company_col = first_existing(raw, ["EMP", "LOJ"])
        counterpart = safe_column(raw, ["CARTAO", "CARTÃO", "BANDEIRA", "ADMINISTRADORA"])
        counterpart = counterpart.mask(counterpart.str.strip().eq(""), "Recebimentos de cartão")
        document = safe_column(raw, ["DUPLICATA"])
        origin_document = safe_column(raw, ["DOC.ORIG", "DOC ORIG"])
        nsu = safe_column(raw, ["NUM.NSU", "NUM NSU", "NRO. NSU"])
        seller = safe_column(raw, ["VENDEDOR"])
        movement, nature = "Cartões", "Entrada"

    elif source == "receber":
        date_col = first_existing(raw, ["VENCTO", "VENCIMENTO", "DTA.VEN"])
        value_col = first_existing(raw, ["V.LIQUI", "V LIQUI", "VALOR LIQUIDO"])
        company_col = first_existing(raw, ["LOJ", "EMP"])
        counterpart = raw[first_existing(raw, ["CLIENTE"])].fillna("").astype(str)
        document = safe_column(raw, ["DUPLICATA", "DOCUMENTO"])
        history = safe_column(raw, ["HISTORICO", "HISTÓRICO"])
        seller = safe_column(raw, ["VEN", "VENDEDOR"])
        movement, nature = "Títulos a receber", "Entrada"

    else:
        date_col = first_existing(raw, ["DTA.VEN", "VENCIMENTO"])
        value_col = first_existing(raw, ["VAL.LIQ", "VAL LIQ", "VALOR LIQUIDO"])
        company_col = first_existing(raw, ["LOJ", "EMP"])
        counterpart = raw[first_existing(raw, ["FORNECEDOR", "FAVORECIDO"])].fillna("").astype(str)
        document = safe_column(raw, ["DUPLICATA", "DOCUMENTO"])
        account = safe_column(raw, ["CONTA", "PLANO DE CONTAS"])
        history = raw.iloc[:, 12].fillna("").astype(str) if raw.shape[1] >= 13 else blank.copy()
        movement, nature = "Títulos a pagar", "Saída"

    out = pd.DataFrame({
        "Data": pd.to_datetime(raw[date_col], dayfirst=True, errors="coerce"),
        "Valor": number_br(raw[value_col]),
        "Empresa": raw[company_col].fillna("").astype(str).str.strip(),
        "Contraparte": counterpart.fillna("").astype(str).str.replace(r"\s+", " ", regex=True).str.strip(),
        "Documento": document.str.replace(r"\s+", " ", regex=True).str.strip(),
        "Documento de origem": origin_document.str.replace(r"\s+", " ", regex=True).str.strip(),
        "NSU": nsu.str.replace(r"\s+", " ", regex=True).str.strip(),
        "Vendedor": seller.str.replace(r"\s+", " ", regex=True).str.strip(),
        "Conta": account.str.replace(r"\s+", " ", regex=True).str.strip(),
        "Histórico": history.str.replace(r"\s+", " ", regex=True).str.strip(),
        "Origem": movement,
        "Natureza": nature,
    }).dropna(subset=["Data", "Valor"])

    # Duplicatas internas de títulos a receber terminadas em “-TE” não representam
    # recebimentos externos e, portanto, são excluídas automaticamente do fluxo.
    if source == "receber":
        documento_normalizado = out["Documento"].fillna("").astype(str).str.strip().str.upper()
        out = out[~documento_normalizado.str.contains(r"-TE\s*$", regex=True, na=False)].copy()

    out = out[out["Valor"].ne(0)].copy()
    out["Entrada"] = np.where(out["Natureza"].eq("Entrada"), out["Valor"], 0.0)
    out["Saída"] = np.where(out["Natureza"].eq("Saída"), out["Valor"], 0.0)
    return out.sort_values("Data").reset_index(drop=True)


def join_unique(series: pd.Series) -> str:
    values = [str(v).strip() for v in series if pd.notna(v) and str(v).strip()]
    return " | ".join(dict.fromkeys(values))


def consolidate_documents(df: pd.DataFrame) -> pd.DataFrame:
    if df.empty:
        return df.copy()
    work = df.copy()
    work["Documento-chave"] = work["Documento"].fillna("").astype(str).str.strip()
    empty = work["Documento-chave"].eq("")
    work.loc[empty, "Documento-chave"] = "SEM_DOC_" + work.index[empty].astype(str)
    groups = ["Origem", "Natureza", "Data", "Documento-chave"]
    result = work.groupby(groups, as_index=False, dropna=False).agg({
        "Valor": "sum", "Entrada": "sum", "Saída": "sum", "Empresa": join_unique,
        "Contraparte": join_unique, "Documento": join_unique, "Documento de origem": join_unique,
        "NSU": join_unique, "Vendedor": join_unique, "Conta": join_unique, "Histórico": join_unique,
    })
    result["Quantidade de lançamentos"] = work.groupby(groups, dropna=False).size().to_numpy()
    return result.drop(columns="Documento-chave").sort_values(["Data", "Natureza", "Valor"], ascending=[True, True, False])


def aggregate_cashflow(df: pd.DataFrame, opening_balance: float, frequency: str) -> pd.DataFrame:
    if df.empty:
        return pd.DataFrame(columns=["Período", "Entradas", "Saídas", "Resultado", "Saldo Projetado"])
    temp = df.copy()
    if frequency == "Diário":
        temp["Período"] = temp["Data"].dt.normalize()
        grouped = temp.groupby("Período", as_index=False)[["Entrada", "Saída"]].sum()
        full = pd.DataFrame({"Período": pd.date_range(grouped["Período"].min(), grouped["Período"].max(), freq="D")})
        grouped = full.merge(grouped, on="Período", how="left").fillna({"Entrada": 0, "Saída": 0})
    elif frequency == "Semanal":
        temp["Período"] = temp["Data"].dt.to_period("W-MON").apply(lambda p: p.start_time)
        grouped = temp.groupby("Período", as_index=False)[["Entrada", "Saída"]].sum()
    else:
        temp["Período"] = temp["Data"].dt.to_period("M").dt.to_timestamp()
        grouped = temp.groupby("Período", as_index=False)[["Entrada", "Saída"]].sum()
    grouped = grouped.rename(columns={"Entrada": "Entradas", "Saída": "Saídas"}).sort_values("Período")
    grouped["Resultado"] = grouped["Entradas"] - grouped["Saídas"]
    grouped["Saldo Projetado"] = opening_balance + grouped["Resultado"].cumsum()
    return grouped


def format_period(value: pd.Timestamp, frequency: str) -> str:
    if frequency == "Diário":
        return value.strftime("%d/%m/%Y")
    if frequency == "Semanal":
        return f"{value:%d/%m} a {(value + timedelta(days=6)):%d/%m/%Y}"
    return value.strftime("%m/%Y")


def kpi_card(label: str, value: str, note: str, css_class: str) -> None:
    st.markdown(
        f'<div class="kpi-card {css_class}"><div class="kpi-label">{label}</div>'
        f'<div class="kpi-value">{value}</div><div class="kpi-note">{note}</div></div>',
        unsafe_allow_html=True,
    )



def render_fullscreen_image(image_b64: str, alt: str) -> None:
    """Exibe a imagem e permite abri-la em uma nova aba, em tamanho integral."""
    data_uri = f"data:image/png;base64,{image_b64}"
    st.markdown(
        f'<a class="guide-image-link" href="{data_uri}" target="_blank" title="Clique para abrir em tela cheia">'
        f'<img src="{data_uri}" alt="{alt}"></a>',
        unsafe_allow_html=True,
    )

def styled_table(df: pd.DataFrame, money_cols: list[str], color_col: str | None = None, color: str = TEXT, height: int = 430):
    styler = df.style
    if money_cols:
        styler = styler.format({c: money_br for c in money_cols if c in df.columns})
    if color_col and color_col in df.columns:
        styler = styler.map(lambda _: f"color:{color};font-weight:800", subset=[color_col])
    st.dataframe(styler, use_container_width=True, hide_index=True, height=height)


def excel_bytes(detail: pd.DataFrame, daily: pd.DataFrame, weekly: pd.DataFrame, monthly: pd.DataFrame) -> bytes:
    output = io.BytesIO()
    with pd.ExcelWriter(output, engine="openpyxl") as writer:
        detail.to_excel(writer, sheet_name="Movimentos", index=False)
        daily.to_excel(writer, sheet_name="Fluxo Diário", index=False)
        weekly.to_excel(writer, sheet_name="Fluxo Semanal", index=False)
        monthly.to_excel(writer, sheet_name="Fluxo Mensal", index=False)
    return output.getvalue()


